/** Device-side synthetic regression, not Xiaomi acceptance. Never ships in the product APK. */
public final class RevisionRunner extends Instrumentation {
    private boolean mediaStarted;private Activity activity;private Bundle arguments;private String stage="start";private File output;private final JSONArray checks=new JSONArray(),images=new JSONArray();
    interface Task {void run() throws Exception;}interface Read<T>{T get()throws Exception;}
    private void ui(Task task)throws Exception{AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new Exception(stage,error.get());}
    private <T>T read(Read<T> read)throws Exception{AtomicReference<T> value=new AtomicReference<>();ui(()->value.set(read.get()));return value.get();}
    private Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private Object call(Object o,String name,Class<?>[] types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}
    private void until(Read<Boolean> condition,String why)throws Exception{long end=SystemClock.uptimeMillis()+90000;while(SystemClock.uptimeMillis()<end){if(condition.get())return;SystemClock.sleep(200);}throw new AssertionError(stage+": "+why);}
    private void check(boolean value,String why){if(!value)throw new AssertionError(stage+": "+why);checks.put(why);Bundle b=new Bundle();b.putString("check",why);sendStatus(0,b);}
    private void key(int code){sendKeyDownUpSync(code);SystemClock.sleep(120);}
    private List<View> tree(){List<View> out=new ArrayList<>();walk(activity.getWindow().getDecorView(),out);return out;}
    private void walk(View v,List<View> out){out.add(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)walk(g.getChildAt(i),out);}}
    private View text(String value){for(View v:tree())if(v.isShown()&&v instanceof TextView&&value.equals(((TextView)v).getText().toString()))return v;return null;}
    private void click(String value)throws Exception{until(()->read(()->text(value)!=null),"missing "+value);ui(()->{View v=text(value);while(v!=null&&!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();if(v==null||!v.performClick())throw new AssertionError("not clickable "+value);});}
    private Activity start(String view){Intent intent=new Intent().setClassName(getTargetContext().getPackageName(),"org.zhixiaoce.aperture.CinemaActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);intent.putExtra("view",view);return startActivitySync(intent);}
    private String stringField(String name)throws Exception{return read(()->((TextView)field(activity,name)).getText().toString());}
    private boolean playingView()throws Exception{return read(()->(Boolean)field(activity,"playingView"));}
    private void waitMedia()throws Exception{until(()->read(()->(Boolean)field(activity,"prepared")&&field(activity,"player")!=null&&((android.media.MediaPlayer)field(activity,"player")).isPlaying()),"media did not start");mediaStarted=true;}
    private void picture(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new AssertionError("no native screenshot");try(FileOutputStream stream=new FileOutputStream(new File(output,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,stream);}b.recycle();images.put(name+".png");}
    private String fetch(String address)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(20000);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>524288)throw new IOException("fixture too large");out.write(b,0,n);}return out.toString("UTF-8");}finally{c.disconnect();}}
    @Override public void onCreate(Bundle args){arguments=args;start();}
    @Override public void onStart(){Bundle result=new Bundle();JSONObject report=new JSONObject();boolean passed=false;try{
        if(!("ranchu".equals(Build.HARDWARE)||"goldfish".equals(Build.HARDWARE))||(getTargetContext().getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)==0)throw new SecurityException("synthetic fixture driver is only for an emulator debug package");output=new File(getTargetContext().getFilesDir(),"s62-revision-tests");output.mkdirs();getTargetContext().getSharedPreferences("cinema-vault",android.content.Context.MODE_PRIVATE).edit().clear().commit();String pack=fetch(arguments.getString("fixture")+"/pack.json");activity=start("movies");stage="atomic native import";
        ui(()->{Class<?> catalog=getTargetContext().getClassLoader().loadClass("org.zhixiaoce.aperture.CinemaCatalog");Method parse=catalog.getDeclaredMethod("config",String.class,String.class,boolean.class);parse.setAccessible(true);Object config=parse.invoke(null,pack,null,true),vault=field(activity,"vault");call(vault,"clear",new Class[]{});Object changed=call(vault,"importConfig",new Class[]{config.getClass()},config);check(Boolean.TRUE.equals(changed),"first synthetic pack saves");check(Boolean.FALSE.equals(call(vault,"importConfig",new Class[]{config.getClass()},config)),"same pack is a no-op, not an append");Object reread=call(vault,"read",new Class[]{});check(((List<?>)field(reread,"lives")).size()==1,"encrypted roundtrip has one live source");activity.finish();});activity=start("movies");
        if(!"true".equals(arguments.getString("channelsOnly"))&&!"true".equals(arguments.getString("skipMovies"))){stage="movie detail and list return";click("S62 测试片单");click("全部");click("下一页");until(()->read(()->text("合成电影13")!=null),"second catalogue page");ui(()->{for(View v:tree())if("合成电影13".equals(String.valueOf(v.getContentDescription()))){v.requestFocus();v.performClick();return;}throw new AssertionError("movie tile missing");});until(()->read(()->text("播放")!=null),"detail missing");
        int plays=read(()->{int n=0;for(View v:tree())if(v.isShown()&&v instanceof Button&&"播放".equals(((Button)v).getText().toString()))n++;return n;});check(plays==1,"single primary play action for single-episode film");check(read(()->"播放".equals(((TextView)activity.getCurrentFocus()).getText().toString())),"detail focuses main play");check(read(()->{for(View v:tree())if(v.isShown()&&v instanceof TextView&&((TextView)v).getText().toString().contains("联网资料未开启"))return false;return true;}),"detail hides internal disabled-network copy");until(()->read(()->{int height=activity.getResources().getDisplayMetrics().heightPixels,width=activity.getResources().getDisplayMetrics().widthPixels;for(View v:tree())if(v instanceof ImageView&&v.getHeight()>=height*.7&&v.getWidth()>=width*.95&&((ImageView)v).getDrawable()!=null&&v.getAlpha()>=.39f)return true;return false;}),"backdrop never loads/fades in");check(true,"actual backdrop image covers at least 70 percent of display height");int imageAlpha=read(()->{int height=activity.getResources().getDisplayMetrics().heightPixels;for(View v:tree())if(v instanceof ImageView&&v.getHeight()>=height*.7)return ((ImageView)v).getImageAlpha();return -1;});report.put("backdropImageAlpha",imageAlpha);check(imageAlpha==255,"backdrop bitmap alpha stays opaque while View fade animates; actual="+imageAlpha);
        check(read(()->{View play=text("播放"),favorite=text("收藏影片");int[] a=new int[2],b=new int[2];play.getLocationOnScreen(a);favorite.getLocationOnScreen(b);return a[0]+play.getWidth()*play.getScaleX()+8<=b[0];}),"focused primary and secondary actions retain a visible gap");
        check(read(()->{for(View v:tree())if(v instanceof TextView){String t=((TextView)v).getText().toString();if(t.contains("2026")&&t.contains("家庭短片")&&t.contains("中国"))return true;}return false;}),"detail shows three real fixture facts");
        check(read(()->{int count=0;for(View v:tree())if(v instanceof LinearLayout&&v.isFocusable()&&String.valueOf(v.getContentDescription()).startsWith("合成电影"))count++;return count==29;}),"same-collection rail contains actual 29 other films, no invented recommendations");picture("detail");
        stage="real MediaPlayer timeline";click("播放");waitMedia();Object media=read(()->field(activity,"player"));check(read(()->((android.media.MediaPlayer)media).getDuration()>15000),"real MP4 duration available");click("播放 / 暂停");until(()->read(()->!((android.media.MediaPlayer)media).isPlaying()),"pause not applied");Object timeline=read(()->field(activity,"timeline"));SeekBar bar=(SeekBar)read(()->field(timeline,"bar"));ui(bar::requestFocus);int before=read(()->((android.media.MediaPlayer)media).getCurrentPosition());key(KeyEvent.KEYCODE_DPAD_RIGHT);check(read(()->(Boolean)field(timeline,"editing")),"D-pad shows seek preview");check(Math.abs(read(()->((android.media.MediaPlayer)media).getCurrentPosition())-before)<1500,"preview does not seek until confirmed");key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->((android.media.MediaPlayer)media).getCurrentPosition()>before+5000),"confirmed seek did not move media");check(read(()->!((android.media.MediaPlayer)media).isPlaying()),"seeking preserves pause intent");picture("timeline");
        ui(()->((Button)field(activity,"playerToggle")).requestFocus());click("播放 / 暂停");until(()->read(()->((View)field(activity,"playerOverlay")).getVisibility()==View.GONE),"controls do not hide");key(KeyEvent.KEYCODE_DPAD_DOWN);check(read(()->((View)field(activity,"playerOverlay")).getVisibility()==View.VISIBLE),"D-pad wakes hidden controls");key(KeyEvent.KEYCODE_BACK);until(()->read(()->text("继续 · 正片")!=null),"saved progress did not create continue action");check(!playingView(),"native watch progress returns as continue action");click("收藏影片");until(()->read(()->text("取消收藏")!=null),"favorite did not persist through detail reload");check(true,"native favorite toggle survives detail reload");key(KeyEvent.KEYCODE_BACK);until(()->read(()->activity.getCurrentFocus()!=null&&"合成电影13".equals(String.valueOf(activity.getCurrentFocus().getContentDescription()))),"catalogue page/focus not restored");check(true,"one playback Back and detail Back restore second-page movie focus");
        ui(activity::finish);activity=start("series");stage="series follow and episode switching";click("S62 合成剧集");click("全部");click("合成剧集");click("追剧");until(()->read(()->text("取消追剧")!=null),"follow state not retained");check(true,"native follow toggle survives detail reload");click("第2集");waitMedia();check(read(()->text("第 2 集 / 共 3 集")!=null),"series timeline identifies episode N of M");ui(()->((android.media.MediaPlayer)field(activity,"player")).seekTo(30000));until(()->read(()->((android.media.MediaPlayer)field(activity,"player")).getCurrentPosition()>20000),"series seek fixture");click("下一集");waitMedia();check(read(()->text("第 3 集 / 共 3 集")!=null&&((android.media.MediaPlayer)field(activity,"player")).getCurrentPosition()<10000),"switching episode resets timeline and updates N/M");}ui(activity::finish);
        activity=start("live");stage="EPG list updates";click("S62 频道");click("测试一组");View focused=read(()->activity.getCurrentFocus());until(()->read(()->{Map<?,?> map=(Map<?,?>)field(activity,"channelProgrammes");for(Object v:map.values())if(((TextView)v).getText().toString().contains("合成当前节目"))return true;return false;}),"XMLTV never reached channel list");check(read(()->activity.getCurrentFocus()==focused),"asynchronous guide update preserves channel-list focus");picture("channels");
        click("合成频道1");waitMedia();Object original=read(()->field(activity,"player"));until(()->read(()->((View)field(activity,"playerOverlay")).getVisibility()==View.GONE),"live controls stay visible");Object pendingPanel=read(()->field(activity,"livePanel"));ui(()->{call(pendingPanel,"show",new Class[]{int.class},0);call(pendingPanel,"key",new Class[]{KeyEvent.class},new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_DOWN));call(pendingPanel,"key",new Class[]{KeyEvent.class},new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_DOWN));});int selectedAfterPost=read(()->(Integer)field(pendingPanel,"selected"));report.put("selectedAfterQueuedFocus",selectedAfterPost);check(selectedAfterPost==1,"queued row focus cannot override a newer selection; actual="+selectedAfterPost);check(read(()->((LinearLayout)field(pendingPanel,"rows")).getChildAt(1).hasFocus()),"latest selected channel retains visible row focus");ui(()->call(pendingPanel,"hide",new Class[]{}));
        ui(()->call(pendingPanel,"show",new Class[]{int.class},0));read(()->field(pendingPanel,"selected"));ui(()->{Handler clock=(Handler)field(pendingPanel,"main");clock.removeCallbacks((Runnable)field(pendingPanel,"hide"));clock.post((Runnable)field(pendingPanel,"hide"));call(pendingPanel,"key",new Class[]{KeyEvent.class},new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_1));call(pendingPanel,"key",new Class[]{KeyEvent.class},new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_1));});check(read(()->(Boolean)call(pendingPanel,"open",new Class[]{})&&"1".equals(field(pendingPanel,"entered"))),"numeric input cancels an already queued idle hide");ui(()->call(pendingPanel,"hide",new Class[]{}));if(!"true".equals(arguments.getString("channelsOnly"))){key(KeyEvent.KEYCODE_DPAD_CENTER);Object sidebar=read(()->field(activity,"livePanel"));check(read(()->(Boolean)call(sidebar,"open",new Class[]{})),"confirm opens same-window channel list");key(KeyEvent.KEYCODE_DPAD_DOWN);check(read(()->field(activity,"player")==original&&((android.media.MediaPlayer)original).isPlaying()),"browsing channel preview retains playing decoder");key(KeyEvent.KEYCODE_BACK);check(read(()->!(Boolean)call(sidebar,"open",new Class[]{})&&field(activity,"player")==original),"Back closes sidebar without tuning");
        key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->!(Boolean)call(sidebar,"open",new Class[]{})),"idle sidebar did not close");check(read(()->field(activity,"player")==original&&((android.media.MediaPlayer)original).isPlaying()),"idle sidebar closes after timeout without tuning or replacing decoder");key(KeyEvent.KEYCODE_DPAD_CENTER);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);waitMedia();check(read(()->(Integer)field(activity,"playingIndex")==1),"confirm switches to previewed channel");key(KeyEvent.KEYCODE_1);key(KeyEvent.KEYCODE_0);key(KeyEvent.KEYCODE_1);key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->(Integer)field(activity,"playingIndex")==2),"numeric 101 did not tune");waitMedia();check(stringField("playerProgramme").contains("合成当前节目3"),"numeric tuning updates current/next programme overlay");
        stage="programme grid";key(KeyEvent.KEYCODE_DPAD_DOWN);click("节目单");Object guide=read(()->field(activity,"programmePanel")),current=read(()->field(activity,"player"));check(read(()->(Boolean)call(guide,"open",new Class[]{})),"programme grid opens");check(read(()->((android.media.MediaPlayer)current).isPlaying()),"programme grid does not pause live video");click("明天");key(KeyEvent.KEYCODE_DPAD_DOWN);check(read(()->((View)field(guide,"horizontal")).hasFocus()),"programme body reachable by Down");check(read(()->((View)field(guide,"horizontal")).getForeground()!=null),"programme body has a visible focus frame");check(read(()->{View today=text("今天"),tomorrow=text("明天");int[] a=new int[2],b=new int[2];today.getLocationOnScreen(a);tomorrow.getLocationOnScreen(b);return a[0]+today.getWidth()*today.getScaleX()+8<=b[0];}),"programme controls retain gaps");key(KeyEvent.KEYCODE_DPAD_RIGHT);until(()->read(()->((HorizontalScrollView)field(guide,"horizontal")).getScrollX()>0),"guide time axis does not scroll");picture("guide");key(KeyEvent.KEYCODE_BACK);check(read(()->!(Boolean)call(guide,"open",new Class[]{})&&field(activity,"player")==current),"guide Back restores same live player");
        stage="terminal media error and Back";ui(()->{Object channel=((List<?>)field(activity,"playingChannels")).get(0);List<String> urls=(List<String>)field(channel,"urls");urls.set(0,arguments.getString("fixture")+"/broken.mp4");call(activity,"playChannels",new Class[]{List.class,int.class,int.class,Runnable.class},field(activity,"playingChannels"),0,0,field(activity,"playerBack"));});until(()->stringField("playerStatus").contains("播放失败"),"broken stream has no error message");String failure=stringField("playerStatus");click("播放 / 暂停");check(failure.equals(stringField("playerStatus")),"play/pause cannot overwrite terminal failure");key(KeyEvent.KEYCODE_BACK);until(()->!playingView(),"error Back did not exit once");check(true,"one Back exits terminal playback failure");}passed=true;
    }catch(Throwable error){try{report.put("error",android.util.Log.getStackTraceString(error));if(output!=null)picture("failure");}catch(Throwable ignored){}}
    try{report.put("passed",passed).put("channelsOnly","true".equals(arguments.getString("channelsOnly"))).put("skipMovies","true".equals(arguments.getString("skipMovies"))).put("stage",stage).put("checks",checks).put("images",images).put("targetPackage",getTargetContext().getPackageName()).put("nativeActivityExecuted",activity!=null).put("realMediaPlayerStarted",mediaStarted).put("syntheticResourcePack",true).put("realXiaomi",false);try(FileOutputStream stream=new FileOutputStream(new File(output,"report.json"))){stream.write(report.toString(2).getBytes("UTF-8"));}result.putString("report",report.toString());if(activity!=null)runOnMainSync(activity::finish);}catch(Throwable error){result.putString("writeError",error.toString());}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
